using Mbb.Archive.Modules.Retention.Application;
using System.Text.Json;using Microsoft.EntityFrameworkCore;using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Retention.Domain.Cases;using Mbb.Archive.Modules.Retention.Domain.Rules;
namespace Mbb.Archive.Modules.Retention.Infrastructure.Persistence;
public sealed class RetentionDbContext:DbContext,IUnitOfWork<RetentionBoundary>,IInbox<RetentionBoundary>,IOutbox<RetentionBoundary>{private readonly List<IIntegrationEvent> _events=[];public RetentionDbContext(DbContextOptions<RetentionDbContext> options):base(options){}internal DbSet<RetentionRule> Rules=>Set<RetentionRule>();internal DbSet<RetentionCase> Cases=>Set<RetentionCase>();internal DbSet<LegalHold> Holds=>Set<LegalHold>();internal DbSet<InboxMessage> Inbox=>Set<InboxMessage>();internal DbSet<OutboxMessage> Outbox=>Set<OutboxMessage>();public Task<bool> HasProcessedAsync(Guid id,CancellationToken ct)=>Inbox.AsNoTracking().AnyAsync(x=>x.Id==id,ct);public void MarkProcessed(Guid id,string name,DateTimeOffset at)=>Inbox.Add(new InboxMessage(id,name,at));public void Enqueue(IIntegrationEvent e)=>_events.Add(e);public override async Task<int> SaveChangesAsync(CancellationToken ct=default){foreach(var e in _events)if(!Outbox.Local.Any(x=>x.Id==e.EventId))Outbox.Add(new OutboxMessage(e.EventId,e.EventName,JsonSerializer.Serialize(e,e.GetType(),new JsonSerializerOptions(JsonSerializerDefaults.Web)),e.OccurredAt));int n;try{n=await base.SaveChangesAsync(ct);}catch(DbUpdateConcurrencyException ex){throw new Mbb.Archive.BuildingBlocks.Application.ConcurrencyConflictException("Kayıt başka bir işlem tarafından değiştirildi. Yenileyip tekrar deneyin.",ex);}catch(DbUpdateException ex)when(ex.InnerException is Npgsql.PostgresException{SqlState:"23505"}){throw new ConcurrencyConflictException("Aynı kayıt için işlem zaten oluşturulmuş. Güncel kaydı yükleyin.",ex);}_events.Clear();return n;}protected override void OnModelCreating(ModelBuilder b){b.HasDefaultSchema("retention");b.ApplyConfigurationsFromAssembly(typeof(RetentionDbContext).Assembly);base.OnModelCreating(b);}}
internal sealed class InboxMessage{private InboxMessage(){}internal InboxMessage(Guid id,string name,DateTimeOffset at){Id=id;EventName=name;ProcessedAt=at;}public Guid Id{get;private set;}public string EventName{get;private set;}=string.Empty;public DateTimeOffset ProcessedAt{get;private set;}}
internal sealed class OutboxMessage{private OutboxMessage(){}internal OutboxMessage(Guid id,string name,string payload,DateTimeOffset at){Id=id;EventName=name;Payload=payload;OccurredAt=at;NextAttemptAt=at;}public Guid Id{get;private set;}public string EventName{get;private set;}=string.Empty;public string Payload{get;private set;}=string.Empty;public DateTimeOffset OccurredAt{get;private set;}public DateTimeOffset NextAttemptAt{get;private set;}public DateTimeOffset? ProcessedAt{get;private set;}public DateTimeOffset? DeadLetteredAt{get;private set;}public int AttemptCount{get;private set;}public string? LastError{get;private set;}public string? LockedBy{get;private set;}public DateTimeOffset? LockedUntil{get;private set;}internal void Lease(string w,DateTimeOffset u){LockedBy=w;LockedUntil=u;}internal void Published(string w,DateTimeOffset n){Ensure(w);ProcessedAt=n;LockedBy=null;LockedUntil=null;}internal void Failed(string w,string er,DateTimeOffset n,DateTimeOffset next,int max){Ensure(w);AttemptCount++;LastError=er.Length<=4000?er:er[..4000];LockedBy=null;LockedUntil=null;if(AttemptCount>=max)DeadLetteredAt=n;else NextAttemptAt=next;}private void Ensure(string w){if(LockedBy!=w)throw new InvalidOperationException("Retention Outbox lease mismatch.");}}
